"""Host regressions; temperature tests use the header generated by idf.py build."""
import os
from pathlib import Path
import subprocess
import tempfile
import unittest

from test_runtime_resources import PROJECT, SUPPORT, run_c, section

BUILD = Path(os.environ.get('IDF_BUILD_DIR', PROJECT / 'build'))


class PeripheralStartupTest(unittest.TestCase):
    def test_spi_borrowed_bus_and_error_propagation(self):
        source = section(PROJECT / 'components/esp_epaper/src/epaper_spi.c',
                         'esp_err_t epd_spi_init(', 'void epd_spi_write_cmd(')
        run_c(r'''
#include <assert.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
typedef int esp_err_t;
#define ESP_OK 0
#define ESP_ERR_INVALID_STATE 1
#define ESP_FAIL 2
#define ESP_LOGE(...) ((void)0)
#define ESP_LOGI(...) ((void)0)
#define GPIO_MODE_OUTPUT 0
#define GPIO_MODE_INPUT 1
#define GPIO_PULLUP_DISABLE 0
#define GPIO_PULLDOWN_DISABLE 0
#define GPIO_INTR_DISABLE 0
#define SPI_DMA_CH_AUTO 0
#define SPI_MAX_CHUNK_SIZE 4096
typedef struct { int mode, pull_up_en, pull_down_en, intr_type; uint64_t pin_bit_mask; } gpio_config_t;
typedef struct { int mosi_io_num, miso_io_num, sclk_io_num, quadwp_io_num, quadhd_io_num, max_transfer_sz; } spi_bus_config_t;
typedef struct { int clock_speed_hz, mode, spics_io_num, queue_size; } spi_device_interface_config_t;
typedef struct { int busy, rst, dc, cs, sck, mosi; } epd_pin_config_t;
typedef struct { int host, speed_hz; bool external_bus; } epd_spi_config_t;
typedef struct { void *spi; int pin_dc, pin_rst, pin_busy, pin_cs; } epd_spi_t;
static int initialized, installs, devices, init_error, add_error;
static void gpio_config(const gpio_config_t *cfg) { (void)cfg; }
static void gpio_set_level(int pin, int level) { (void)pin; (void)level; }
static int spi_bus_initialize(int host, const spi_bus_config_t *cfg, int dma) {
    (void)host; (void)cfg; (void)dma; installs++;
    if (init_error) return init_error;
    if (initialized) return ESP_ERR_INVALID_STATE;
    initialized = 1; return ESP_OK;
}
static int spi_bus_add_device(int host, const spi_device_interface_config_t *cfg, void **handle) {
    (void)host; (void)cfg;
    if (!initialized || add_error) return ESP_FAIL;
    *handle = (void *)1; devices++; return ESP_OK;
}
static void spi_bus_remove_device(void *handle) { assert(handle); devices--; }
''' + source + r'''
int main(void) {
    epd_spi_t spi = {0};
    epd_pin_config_t pins = {.busy=8, .rst=9, .dc=17, .cs=18, .sck=40, .mosi=45};
    epd_spi_config_t cfg = {.host=2, .speed_hz=10000000, .external_bus=true};
    initialized = 1; /* Owned by Board Manager, shared with LoRa. */
    for (int i = 0; i < 20; ++i) {
        assert(epd_spi_init(&spi, &pins, &cfg) == ESP_OK);
        assert(installs == 0 && devices == 1);
        assert(epd_spi_deinit(&spi) == ESP_OK);
        assert(initialized && devices == 0);
    }
    add_error = ESP_FAIL;
    assert(epd_spi_init(&spi, &pins, &cfg) == ESP_FAIL && installs == 0);
    add_error = 0; initialized = 0;
    assert(epd_spi_init(&spi, &pins, &cfg) == ESP_FAIL && installs == 0);
    cfg.external_bus = false;
    assert(epd_spi_init(&spi, &pins, &cfg) == ESP_OK && installs == 1);
    assert(epd_spi_deinit(&spi) == ESP_OK);
    initialized = 0; init_error = ESP_FAIL;
    assert(epd_spi_init(&spi, &pins, &cfg) == ESP_FAIL && devices == 0);
}
''')

    def test_temperature_conversion_and_bounded_startup_wait(self):
        header = BUILD / 'sensorlib_compat/GaugeAXP2602.hpp'
        conversion = section(header, '        // Read die temperature', '        // Read battery status')
        wait = section(PROJECT / 'main/test_battery.cpp', 'static esp_err_t wait_battery_adc(',
                       'static esp_err_t init_battery_gauge(')
        harness = r'''
#include <cassert>
#include <cmath>
#include <cstdint>
using std::isfinite;
using std::isnan;
static unsigned warnings, elapsed, attempts;
static int raw = 3415, invalid_reads;
static bool io_error, refresh_error;
static void log_w(const char *, ...) __attribute__((format(printf, 1, 2)));
static void log_w(const char *, ...) { warnings++; }
typedef int esp_err_t;
#define ESP_OK 0
#define ESP_FAIL 1
#define ESP_ERR_TIMEOUT 2
#define ESP_LOGE(...) ((void)0)
#define BATTERY_ADC_RETRY_MS 50U
#define BATTERY_ADC_ATTEMPTS 10U
#define pdMS_TO_TICKS(ms) (ms)
static void vTaskDelay(unsigned ms) { elapsed += ms; }
class GaugeAXP2602 {
public:
    struct { float actualDieTemperature; uint16_t tdieTemperatureRaw; } data = {};
    enum { REG_TDIE_ADC_HIGH, REG_TDIE_ADC_LOW };
    int readReg(int reg) {
        if (io_error) return -1;
        int sample = invalid_reads > 0 ? 0 : raw;
        return reg == REG_TDIE_ADC_HIGH ? sample >> 8 : sample & 255;
    }
    bool refresh() {
        attempts++;
        if (refresh_error) return false;
CONVERSION
        if (invalid_reads > 0) invalid_reads--;
        return true;
    }
    float getThermalDieTemperature() { return data.actualDieTemperature; }
    unsigned getThermalDieTemperatureRaw() { return data.tdieTemperatureRaw; }
};
WAIT
int main() {
    GaugeAXP2602 gauge;
    assert(gauge.refresh() && gauge.getThermalDieTemperature() == 26.0f);
    raw = 3662; /* A real zero degrees sample must remain valid. */
    assert(gauge.refresh() && gauge.getThermalDieTemperature() == 0.0f);
    raw = 0;
    assert(gauge.refresh() && isnan(gauge.getThermalDieTemperature()));
    raw = 8191;
    assert(gauge.refresh() && isnan(gauge.getThermalDieTemperature()));
    raw = 3415; assert(gauge.refresh()); io_error = true;
    assert(gauge.refresh() && isnan(gauge.getThermalDieTemperature()));
    io_error = false; invalid_reads = 2; elapsed = attempts = 0;
    assert(wait_battery_adc(gauge) == ESP_OK && attempts == 3 && elapsed == 150);
    invalid_reads = 100; elapsed = attempts = 0;
    assert(wait_battery_adc(gauge) == ESP_ERR_TIMEOUT && attempts == 10 && elapsed == 500);
    refresh_error = true; elapsed = attempts = 0;
    assert(wait_battery_adc(gauge) == ESP_FAIL && attempts == 1);
    assert(warnings > 0);
}
'''.replace('CONVERSION', conversion).replace('WAIT\n', wait + '\n')
        with tempfile.TemporaryDirectory() as tmp:
            src = Path(tmp) / 'temperature.cpp'
            exe = Path(tmp) / 'temperature'
            src.write_text(harness)
            subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-Werror',
                            str(src), '-o', str(exe)], check=True)
            subprocess.run([str(exe)], check=True)


if __name__ == '__main__':
    unittest.main()
